// a.rs — ripgrep 演练沙盒文件 A
pub fn parse_config(path: &str) -> Option<String> {
    // TODO: 支持 TOML 与 YAML 双格式
    let raw = std::fs::read_to_string(path).ok()?;
    Some(raw.trim().to_string())
}

pub fn boot() {
    let cfg = parse_config("app.toml").unwrap(); // FIXME: 生产路径应优雅降级
    let _ = cfg;
}

// b.rs — ripgrep 演练沙盒文件 B
fn checksum(data: &[u8]) -> u32 {
    // TODO: 换 CRC32 替代累加和
    data.iter().fold(0u32, |acc, b| acc.wrapping_add(*b as u32))
}

pub fn legacy() {
    let v: Vec<u32> = vec![1, 2, 3];
    let first = v.first().unwrap();
    let _ = first;
    let last = v.last().unwrap();
    let _ = last;
    let _ = checksum(&[1, 2, 3]);
}

// c.rs — ripgrep 演练沙盒文件 C
pub fn retry(times: u32) {
    // FIXME: 指数退避还没实现,固定 sleep
    for _ in 0..times {
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
}

pub fn label(tag: &str) -> String {
    // TODO: 加 i18n 翻译层
    format!("[{tag}]")
}
